const items = $input.all();

return items.map((item, index) => {
  let raw = item.json.output;

  if (typeof raw === 'string') {
    raw = raw
      .replace(/```json\s*/gi, '')
      .replace(/```javascript\s*/gi, '')
      .replace(/```\s*/g, '')
      .replace(/^`+|`+$/g, '')
      .trim();
  }

  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(`Item ${index}: La salida de la IA no es JSON válido. Error: ${error.message}`);
  }

  // ✅ ÚNICA validación necesaria según tu salida real
  if (!parsed.temas || !Array.isArray(parsed.temas)) {
    throw new Error(`Item ${index}: Falta el array 'temas' o no es válido`);
  }

  return {
    json: parsed
  };
});

// ===============================
// Parse + Transform to Slides
// ===============================
const items = $input.all();
const item = items[0]?.json || {};
let parsed = item;

// Si viene como string, parsearlo
if (typeof item === 'string') {
  try {
    parsed = JSON.parse(item);
  } catch (e) {
    return [{
      json: {
        success: false,
        error: 'No se pudo parsear JSON',
        raw: item
      }
    }];
  }
}

// Si es un array con un objeto dentro, extraerlo
if (Array.isArray(parsed) && parsed.length === 1) {
  parsed = parsed[0];
}

// Validar que tenga la estructura esperada
if (!parsed.temas && !parsed.secciones && !parsed.trivia) {
  return [{
    json: {
      success: false,
      error: 'Estructura JSON no válida - faltan propiedades esperadas',
      raw: parsed
    }
  }];
}

const output = [];

// ===============================
// VERIFICAR QUÉ SECCIONES EXISTEN EN TEMAS
// ===============================
let tienePortadaEnTemas = false;
let tieneTriviaEnTemas = false;
let tieneBibliografiaEnTemas = false;
let tieneCreditosEnTemas = false;

if (Array.isArray(parsed.temas)) {
  for (const tema of parsed.temas) {
    const nombreTema = (tema.nombre || "").toLowerCase();

    if (nombreTema === "portada") tienePortadaEnTemas = true;
    if (nombreTema === "trivia") tieneTriviaEnTemas = true;
    if (nombreTema.includes("bibliografía") || nombreTema.includes("bibliografia")) tieneBibliografiaEnTemas = true;
    if (nombreTema === "créditos" || nombreTema === "creditos") tieneCreditosEnTemas = true;
  }
}

// 1️⃣ PORTADA (siempre primero, solo si NO está en temas)
if (!tienePortadaEnTemas) {
  output.push({
    json: {
      seccion: "Portada",
      subseccion: "portada",
      slide: 1,
      plantilla: 8
    }
  });
}

// 2️⃣ TEMAS - convertir a slides
if (Array.isArray(parsed.temas)) {
  for (const tema of parsed.temas) {
    const nombreTema = tema.nombre || "";
    const nombreTemaLower = nombreTema.toLowerCase();

    // Determinar plantilla según el tipo de sección
    let plantilla = 2; // Por defecto

    if (nombreTemaLower === "portada") {
      plantilla = 8;
    } else if (nombreTemaLower === "trivia") {
      plantilla = 10;
    } else if (nombreTemaLower.includes("bibliografía") || 
               nombreTemaLower.includes("bibliografia") || 
               nombreTemaLower === "créditos" || 
               nombreTemaLower === "creditos") {
      plantilla = 5;
    }

    if (Array.isArray(tema.subtemas)) {
      for (const subtema of tema.subtemas) {
        const nombreSubtema = subtema.nombre || "";

        // Primer slide del subtema (con sección y subsección)
        output.push({
          json: {
            seccion: nombreTema,
            subseccion: nombreSubtema,
            slide: 1,
            plantilla: plantilla
          }
        });

        // Slides adicionales según el contenido (solo para temas normales, no para secciones especiales)
        if (plantilla === 2 && Array.isArray(subtema.contenido)) {
          const numSlides = subtema.contenido.filter(c => c !== "").length || subtema.contenido.length;

          for (let i = 1; i < numSlides; i++) {
            output.push({
              json: {
                seccion: "",
                subseccion: "",
                slide: i + 1,
                plantilla: 2
              }
            });
          }
        }
      }
    }
  }
}

// 3️⃣ SECCIONES ADICIONALES
if (Array.isArray(parsed.secciones)) {
  for (const seccion of parsed.secciones) {
    const nombreSeccion = seccion.nombre || "";

    if (Array.isArray(seccion.subtemas)) {
      for (const subtema of seccion.subtemas) {
        const nombreSubtema = subtema.nombre || "";

        output.push({
          json: {
            seccion: nombreSeccion,
            subseccion: nombreSubtema,
            slide: 1,
            plantilla: 2
          }
        });

        // Slides adicionales si existen
        if (Array.isArray(subtema.contenido)) {
          const numSlides = subtema.contenido.filter(c => c !== "").length || subtema.contenido.length;

          for (let i = 1; i < numSlides; i++) {
            output.push({
              json: {
                seccion: "",
                subseccion: "",
                slide: i + 1,
                plantilla: 2
              }
            });
          }
        }
      }
    }
  }
}

// 4️⃣ TRIVIA (solo si NO está en temas)
if (!tieneTriviaEnTemas && parsed.trivia) {
  output.push({
    json: {
      seccion: parsed.trivia.nombre || "Trivia",
      subseccion: parsed.trivia.nombre || "Trivia",
      slide: 1,
      plantilla: 10
    }
  });
}

// 5️⃣ BIBLIOGRAFÍA (solo si NO está en temas)
const bibliografia = parsed.bibliografia || parsed.bibliografia_y_mas_informacion;
if (!tieneBibliografiaEnTemas && bibliografia) {
  output.push({
    json: {
      seccion: bibliografia.nombre || "Bibliografía y más información",
      subseccion: bibliografia.nombre || "Bibliografía y más información",
      slide: 1,
      plantilla: 5
    }
  });
}

// 6️⃣ CRÉDITOS (solo si NO está en temas)
if (!tieneCreditosEnTemas && parsed.creditos) {
  output.push({
    json: {
      seccion: parsed.creditos.nombre || "Créditos",
      subseccion: parsed.creditos.nombre || "Créditos",
      slide: 1,
      plantilla: 5
    }
  });
}

return output;

// Entrada: items (cada item.json: row_number, seccion, subseccion, slide, plantilla, titulo/prompt)
// Salida: lista de items: [{json:{...}}, {json:{...}}, ...]

const rows = items
  .map(i => i.json)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

// Tema principal de portada
const temaPortada = $('Obtener campos del formulario').first().json.inf_tema;

const seccionesMap = {};
let currentSection = null;
let currentSubtopic = null;

// Mapeo de plantillas para referencia
const plantillaPorSeccionSubtema = {};

// Primera pasada: guardar plantilla de cada fila
for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();
  const plantilla = row.plantilla;

  if (seccion && subseccion) {
    // Guardar la plantilla para esta combinación sección/subsección
    const key = `${seccion}||${subseccion}`;
    plantillaPorSeccionSubtema[key] = plantilla;
  }
}

// Segunda pasada: construir la estructura
for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();

  // Nueva sección
  if (seccion) {
    if (!seccionesMap[seccion]) {
      seccionesMap[seccion] = { nombre: seccion, subtemas: [] };
    }

    currentSection = seccionesMap[seccion];
    currentSubtopic = null;
  }

  // Nueva subsección (slide 1)
  if (subseccion) {
    if (!currentSection) continue;

    const key = `${seccion}||${subseccion}`;
    const plantilla = plantillaPorSeccionSubtema[key];

    currentSubtopic = { nombre: subseccion };

    // Asignar plantilla si existe
    if (plantilla) {
      currentSubtopic.plantilla = plantilla;
    }

    // Solo agregar contenido si no es Portada o Trivia
    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido = [""];
    }

    currentSection.subtemas.push(currentSubtopic);
    continue;
  }

  // Fila sin sección ni subsección → slides adicionales
  if (!seccion && !subseccion) {
    if (!currentSubtopic) continue;

    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido.push("");
    }
  }
}

// ---- POSTPROCESO PORTADA ----
if (seccionesMap["Portada"]) {
  const portada = seccionesMap["Portada"];
  const sub = portada.subtemas[0];

  // Portada no lleva contenido
  if (sub) {
    delete sub.contenido;
  }

  // Insertar el título correcto proveniente del nodo externo
  if (sub) {
    sub.titulo = temaPortada;
  }

  // Verificar si la portada tiene plantilla 8 antes de agregar prompt
  if (sub && sub.plantilla === 8) {
    // Generar prompt específico para plantilla 8 (Portada)
    portada.prompt = `Genera una imagen sobre ${temaPortada}.`;
  }
}

// ---- POSTPROCESO TRIVIA ----
if (seccionesMap["Trivia"]) {
  const trivia = seccionesMap["Trivia"];
  const sub = trivia.subtemas[0];

  if (sub) {
    delete sub.contenido;
    delete sub.titulo;
  }
}

// ---- GENERAR PROMPTS PARA PLANTILLAS 2 Y 8 ----
// Primero, procesar prompts a nivel de subtema
for (const nombre of Object.keys(seccionesMap)) {
  const seccion = seccionesMap[nombre];

  for (const subtema of seccion.subtemas) {
    // Verificar si el subtema tiene plantilla 2 o 8
    if (subtema.plantilla === 2 || subtema.plantilla === 8) {
      // Generar prompt para imágenes basado en el nombre del subtema
      if (subtema.plantilla === 2) {
        // Para plantilla 2 (contenido normal)
        subtema.prompt = `Genera una imagen sobre "${subtema.nombre}" en el contexto de ${seccion.nombre}.`;
      } else if (subtema.plantilla === 8) {
        // Para plantilla 8 (portada) - ya se procesó arriba
        // Solo asegurar que esté presente
        if (!seccion.prompt && subtema.nombre.toLowerCase() === "portada") {
          seccion.prompt = `Genera una imagen sobre ${temaPortada}.`;
        }
      }
    }
  }
}

// ---- GENERAR LISTA ORDENADA ----
const output = [];

// Portada primero
if (seccionesMap["Portada"]) {
  output.push({ json: seccionesMap["Portada"] });
}

// Otras secciones
for (const nombre of Object.keys(seccionesMap)) {
  if (nombre === "Portada" || nombre === "Trivia") continue;
  output.push({ json: seccionesMap[nombre] });
}

// Trivia última
if (seccionesMap["Trivia"]) {
  output.push({ json: seccionesMap["Trivia"] });
}

return output;

const data = {
  tema: $('Obtener campos del formulario').first().json.inf_tema,
  estilo: $('Obtener campos del formulario').first().json.inf_estilo,
  estilo_grafico: $('Obtener campos del formulario').first().json.inf_estilo_grafico,
  audiencia: $('Obtener campos del formulario').first().json.inf_audiencia,
  secciones_sugeridas: $('Obtener campos del formulario').first().json.inf_secciones_sugeridas || "",
  experto_en: $('Obtener campos del formulario').first().json.inf_experto,
  id_carpeta_drive: $('Create folder').first().json.id
};

return {
  json: {
    datos_json: JSON.stringify(data)
  }
};

// ===============================
// ORDENAR FILAS
// ===============================
const rows = items
  .map(i => i.json)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

// Tema para la portada
const temaPortada = $('Obtener campos del formulario').first().json.inf_tema;

const seccionesMap = {};
const ordenAparicion = [];

let currentSection = null;
let currentSubtopic = null;

// ===============================
// CONSTRUIR SECCIONES
// ===============================
for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();
  const texto = row.texto || "";

  // --- Nueva sección ---
  if (seccion) {
    if (!seccionesMap[seccion]) {
      seccionesMap[seccion] = {
        nombre: seccion,
        subtemas: []
      };
      ordenAparicion.push(seccion);
    }
    currentSection = seccionesMap[seccion];
    currentSubtopic = null;
  }

  // --- Nueva subsección ---
  if (subseccion) {
    if (!currentSection) continue;

    currentSubtopic = { nombre: subseccion };

    if (currentSection.nombre.toLowerCase() === "portada") {
      currentSubtopic.titulo = texto;
    } else {
      currentSubtopic.contenido = [texto];
    }

    currentSection.subtemas.push(currentSubtopic);
    continue;
  }

  // --- Slides adicionales ---
  if (!seccion && !subseccion && currentSubtopic) {
    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido.push(texto);
    }
  }
}

// ===============================
// POSTPROCESO PORTADA
// ===============================
if (seccionesMap["Portada"]) {
  const portada = seccionesMap["Portada"];
  const sub = portada.subtemas[0];

  if (sub) {
    delete sub.contenido;
    sub.titulo = temaPortada;
  }

  portada.prompt = `Genera una imagen en formato PNG, no texto, solo imagen, sobre el tema ${temaPortada}. No incluyas ninguna descripción, solo devuelve la imagen.`;
}

// ===============================
// POSTPROCESO TRIVIA
// ===============================
if (seccionesMap["Trivia"]) {
  const trivia = seccionesMap["Trivia"];
  const sub = trivia.subtemas[0];
  if (sub) {
    delete sub.contenido;
    delete sub.titulo;
  }
}

// ===============================
// ORDEN FINAL FORZADO
// ===============================
const output = [];

// 1. Portada
if (seccionesMap["Portada"]) {
  output.push({ json: seccionesMap["Portada"] });
}

// 2. Contenidos normales
for (const nombre of ordenAparicion) {
  if (
    nombre !== "Portada" &&
    nombre !== "Trivia" &&
    nombre !== "Bibliografía y más información" &&
    nombre !== "Créditos"
  ) {
    output.push({ json: seccionesMap[nombre] });
  }
}

// 3. Trivia
if (seccionesMap["Trivia"]) {
  output.push({ json: seccionesMap["Trivia"] });
}

// 4. Bibliografía
if (seccionesMap["Bibliografía y más información"]) {
  output.push({ json: seccionesMap["Bibliografía y más información"] });
}

// 5. Créditos
if (seccionesMap["Créditos"]) {
  output.push({ json: seccionesMap["Créditos"] });
}

return output;

// Función para convertir caracteres Unicode a entidades HTML
const convertirAEntidadesHTML = (texto) => {
  if (!texto) return texto;

  return texto
    // Convertir exponentes superíndice
    .replace(/⁰/g, '<sup>0</sup>')
    .replace(/¹/g, '<sup>1</sup>')
    .replace(/²/g, '<sup>2</sup>')
    .replace(/³/g, '<sup>3</sup>')
    .replace(/⁴/g, '<sup>4</sup>')
    .replace(/⁵/g, '<sup>5</sup>')
    .replace(/⁶/g, '<sup>6</sup>')
    .replace(/⁷/g, '<sup>7</sup>')
    .replace(/⁸/g, '<sup>8</sup>')
    .replace(/⁹/g, '<sup>9</sup>')
    .replace(/⁻/g, '<sup>-</sup>')
    // Convertir subíndices si los hay
    .replace(/₀/g, '<sub>0</sub>')
    .replace(/₁/g, '<sub>1</sub>')
    .replace(/₂/g, '<sub>2</sub>')
    .replace(/₃/g, '<sub>3</sub>')
    .replace(/₄/g, '<sub>4</sub>')
    .replace(/₅/g, '<sub>5</sub>')
    .replace(/₆/g, '<sub>6</sub>')
    .replace(/₇/g, '<sub>7</sub>')
    .replace(/₈/g, '<sub>8</sub>')
    .replace(/₉/g, '<sub>9</sub>')
    // Convertir símbolo de multiplicación
    .replace(/×/g, '&times;')
    // Otros símbolos comunes en textos científicos
    .replace(/±/g, '&plusmn;')
    .replace(/÷/g, '&divide;')
    .replace(/≤/g, '&le;')
    .replace(/≥/g, '&ge;')
    .replace(/≈/g, '&asymp;')
    .replace(/≠/g, '&ne;')
    .replace(/°/g, '&deg;');
};

const out = [];

for (const it of items) {
  const j = it.json || {};
  // Texto original (puede ser HTML con <p>..</p> o texto plano)
  const texto = (j.sld_texto1 || "").trim();

  // Si no hay texto, devolvemos un item con texto vacío
  if (!texto) {
    out.push({ json: { ...j, sld_texto1: "" } });
    continue;
  }

  // Dividir en párrafos:
  // - Primero intentamos por doble salto de línea (caso más común)
  // - Si no hay doble salto, dejamos el texto entero como un solo párrafo
  const partes = texto.split(/\n\s*\n/).map(s => s.trim()).filter((s) => s !== "");

  // Base para el orden (si no existe, asumimos 1)
  const baseOrden = Number(j.sld_orden) || 1;

  // Crear un item por cada párrafo
  partes.forEach((parrafo, idx) => {
    const nuevo = { ...j }; // copiamos todos los campos (incluye sld_id_subseccion)

    // Convertir caracteres Unicode problemáticos a entidades HTML
    nuevo.sld_texto1 = convertirAEntidadesHTML(parrafo);

    // Ajustamos el orden para que cada párrafo tenga un orden incremental
    nuevo.sld_orden = baseOrden + idx;

    out.push({ json: nuevo });
  });
}

return out;

const out = [];

for (const item of items) {
  const temaId = item.json.sec_id;
  const subtemas = item.json.subtemas || [];

  subtemas.forEach((st, idx) => {
    out.push({
      json: {
        idTema: temaId,
        nombre: st.nombre,
        contenido: st.contenido || "", // array de párrafos
        orden: idx + 1,
        titulo: st.titulo || st.nombre
      }
    });
  });
}

return out;

// Función para convertir Markdown a HTML
function markdownToHtml(markdown) {
  if (!markdown || typeof markdown !== 'string') return '';

  let html = markdown;

  // 1. Limpiar backslashes escapados (PRIMERO)
  html = html
    .replace(/\\\*/g, '*')      // \* → *
    .replace(/\\_/g, '_')       // \_ → _
    .replace(/\\#/g, '#')       // \# → #
    .replace(/\\-/g, '-')       // \- → -
    .replace(/\\\[/g, '[')      // \[ → [
    .replace(/\\\]/g, ']')      // \] → ]
    .replace(/\\\(/g, '(')      // \( → (
    .replace(/\\\)/g, ')');     // \) → )

  // 2. Convertir saltos de línea especiales
  html = html.replace(/\\n\\n/g, '\n\n');  // \\n\\n → \n\n

  // 3. Convertir headers (###, ####)
  html = html.replace(/^#### (.*$)/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.*$)/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.*$)/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.*$)/gm, '<h1>$1</h1>');

  // 4. Convertir negritas e itálicas (***texto*** → <strong><em>texto</em></strong>)
  html = html.replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>');
  html = html.replace(/\_\_\_(.*?)\_\_\_/g, '<strong><em>$1</em></strong>');

  // 5. Convertir negritas (**texto** o __texto__)
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\_\_(.*?)\_\_/g, '<strong>$1</strong>');

  // 6. Convertir itálicas (*texto* o _texto_)
  html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');
  html = html.replace(/\_(.*?)\_/g, '<em>$1</em>');

  // 7. Convertir listas no ordenadas
  const ulRegex = /(?:^|\n)((?:[-*+] .+\n?)+)/g;
  html = html.replace(ulRegex, function(match, list) {
    const items = list.trim().split('\n').map(item => {
      const text = item.replace(/^[-*+] /, '').trim();
      return `<li>${text}</li>`;
    }).join('\n');
    return `<ul>\n${items}\n</ul>`;
  });

  // 8. Convertir listas ordenadas
  const olRegex = /(?:^|\n)((?:\d+\. .+\n?)+)/g;
  html = html.replace(olRegex, function(match, list) {
    const items = list.trim().split('\n').map(item => {
      const text = item.replace(/^\d+\. /, '').trim();
      return `<li>${text}</li>`;
    }).join('\n');
    return `<ol>\n${items}\n</ol>`;
  });

  // 9. Convertir párrafos (texto separado por \n\n)
  const paragraphs = html.split('\n\n').filter(p => p.trim());
  html = paragraphs.map(p => {
    p = p.trim();
    // No envolver en <p> si ya es un elemento de bloque
    if (p.startsWith('<h') || p.startsWith('<ul') || p.startsWith('<ol') || 
        p.startsWith('<li') || p.startsWith('<blockquote')) {
      return p;
    }
    return `<p>${p.replace(/\n/g, ' ')}</p>`;
  }).join('\n');

  // 10. Limpiar saltos de línea extra
  html = html.replace(/\n{3,}/g, '\n\n');

  return html.trim();
}

// ===============================
// Procesamiento principal
// ===============================
const out = [];

for (const item of items) {
  const subId = item.json.sub_id;
  const nombre = item.json.nombre || "";
  const parrafos = Array.isArray(item.json.contenido) ? item.json.contenido : [item.json.contenido];

  // Determinar plantilla
  let plantilla = 2; // valor por defecto
  if (nombre.toLowerCase() === "portada") {
    plantilla = 8;
  } else if (nombre.toLowerCase() === "trivia") {
    plantilla = 10;
  } else if (nombre.toLowerCase() === "bibliografía y más información" ||   
             nombre.toLowerCase() === "créditos") {
    plantilla = 5;
  }

  parrafos.forEach((texto, idx) => {
    // Convertir Markdown a HTML
    const htmlTexto = texto ? markdownToHtml(texto) : "";

    out.push({
      json: {
        sld_activo: true,
        sld_id_subseccion: subId,
        sld_nombre: nombre,
        sld_orden: idx + 1,
        sld_plantilla: plantilla,
        sld_texto1: htmlTexto, // HTML convertido
        sld_titulo: item.json.titulo || nombre
      }
