let html = "";
let texto2 = "";

// =======================================
// FUNCIÓN PARA CONVERTIR MARKDOWN A HTML
// =======================================
function markdownToHTML(text) {
  if (!text || typeof text !== 'string') return text;

  let converted = text;

  // 1. Convertir saltos de línea (ambos formatos)
  converted = converted.replace(/\\n\\n/g, '<br><br>');
  converted = converted.replace(/\n\n/g, '<br><br>');

  // 2. Convertir encabezados (antes de negritas para evitar conflictos)
  converted = converted.replace(/####\s+(.+?)(?=<br>|$)/g, '<h4>$1</h4>');
  converted = converted.replace(/###\s+(.+?)(?=<br>|$)/g, '<h3>$1</h3>');

  // 3. Convertir listas ordenadas
  // Patrón: captura bloques de líneas que empiezan con "1.", "2.", etc.
  converted = converted.replace(/(?:^|\n)((?:\d+\.\s+.+(?:\n|$))+)/gm, function(match, listContent) {
    const items = listContent.trim().split(/\n/).map(line => {
      return line.replace(/^\d+\.\s+/, '').trim();
    }).filter(item => item.length > 0);

    if (items.length === 0) return match;
    const listItems = items.map(item => `<li>${item}</li>`).join('');
    return `<ol>${listItems}</ol>`;
  });

  // 4. Convertir listas no ordenadas
  // Patrón: captura bloques de líneas que empiezan con "-"
  converted = converted.replace(/(?:^|\n)((?:-\s+.+(?:\n|$))+)/gm, function(match, listContent) {
    const items = listContent.trim().split(/\n/).map(line => {
      return line.replace(/^-\s+/, '').trim();
    }).filter(item => item.length > 0);

    if (items.length === 0) return match;
    const listItems = items.map(item => `<li>${item}</li>`).join('');
    return `<ul>${listItems}</ul>`;
  });

  // 5. Convertir negrita y cursiva combinadas (debe ir antes que negrita o cursiva solas)
  converted = converted.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');

  // 6. Convertir negrita
  converted = converted.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

  // 7. Convertir cursiva
  converted = converted.replace(/\*(.+?)\*/g, '<em>$1</em>');

  // 8. Limpiar saltos de línea sueltos que quedaron
  converted = converted.replace(/\n/g, ' ');

  return converted;
}

// =======================================
// FUNCIÓN PARA NORMALIZAR TEXTO (COMPARACIÓN)
// =======================================
function normalizarTextoParaComparacion(texto) {
  if (!texto || typeof texto !== 'string') return '';

  return texto
    .toLowerCase()
    .replace(/<[^>]*>/g, '')         // Eliminar HTML
    .replace(/\*\*/g, '')            // Eliminar markdown bold
    .replace(/\*/g, '')              // Eliminar markdown italic
    .replace(/\[.*?\]/g, '')         // Eliminar enlaces markdown
    .replace(/\(.*?\)/g, '')         // Eliminar paréntesis con contenido
    .replace(/\s+/g, ' ')            // Unificar espacios múltiples
    .replace(/[.,;:!?\-_'"`´]/g, '') // Eliminar puntuación y caracteres especiales
    .trim()
    .substring(0, 300);              // Usar primeros 300 chars (suficiente para match)
}

// =======================================
// FUNCIÓN HELPER PARA OBTENER ITEMS DE FORMA SEGURA
// =======================================
const obtenerItemsSeguro = (nombreNodo) => {
  try {
    const items = $items(nombreNodo);
    return items || [];
  } catch (error) {
    console.log(`⚠️ Nodo "${nombreNodo}" no encontrado o desactivado`);
    return [];
  }
};

// =======================================
// Obtener información del formulario
// =======================================
const formularioItems = obtenerItemsSeguro("Obtener campos del formulario");
const formulario = formularioItems.length > 0 ? formularioItems[0].json : {};

// Parsear inf_parametros
let parametros = {};
if (formulario.inf_parametros) {
  try {
    parametros = JSON.parse(formulario.inf_parametros);
  } catch (e) {
    parametros = {};
  }
}

// =======================================
// Obtener Información General
// =======================================
const infoItems = obtenerItemsSeguro("Información General");
const info = infoItems.length > 0 ? infoItems[0].json : {};
const ig = info.informacion_general || {};

// =======================================
// ENCABEZADO HTML
// =======================================
html += `<h1>📘 ${formulario.inf_nombre || "TÍTULO NO ESPECIFICADO"}</h1>`;
html += `<p><b>Guion teórico para infografía interactiva</b></p>`;
html += `<hr><br><br>`;

html += `<h2>1. INFORMACIÓN GENERAL</h2><br>`;
html += `<p><b>Título del recurso:</b><br>${formulario.inf_nombre || "No especificado"}</p><br>`;
html += `<p><b>Tipo de recurso:</b><br>${ig.tipo_recurso || "No especificado"}</p><br>`;
html += `<p><b>Nivel educativo:</b><br>${ig.nivel_educativo || "No especificado"}</p><br>`;
html += `<p><b>Área:</b><br>${ig.area || "No especificado"}</p><br>`;
html += `<p><b>Palabras clave:</b><br>`;
html += Array.isArray(ig.palabras_clave) ? ig.palabras_clave.join(", ") : "No especificadas";
html += `</p><br>`;
html += `<p><b>Resumen académico</b><br>${info.resumen_academico || "No disponible"}</p><br>`;

if (Array.isArray(info.objetivos_aprendizaje) && info.objetivos_aprendizaje.length) {
  html += `<p><strong>Objetivos de aprendizaje</strong></p><ul>`;
  info.objetivos_aprendizaje.forEach(obj => {
    html += `<li>${obj}</li>`;
  });
  html += `</ul>`;
}

html += `<br>`;

if (Array.isArray(info.competencias) && info.competencias.length) {
  html += `<p><strong>Competencias</strong></p><ul>`;
  info.competencias.forEach(comp => {
    html += `<li>${comp}</li>`;
  });
  html += `</ul>`;
}

html += `<br><hr><br><br>`;

// =======================================
// PROMPTS POR TEXTO BASE (CON NORMALIZACIÓN)
// =======================================
const itemsPrompts = obtenerItemsSeguro("Generar prompts");
const promptsPorTexto = {};
const promptsDebugInfo = []; // Para debugging

itemsPrompts.forEach((item, index) => {
  const meta = item.json?.metadata || {};
  const textoBase = (meta.texto_base || "").trim();

  if (textoBase) {
    const textoNormalizado = normalizarTextoParaComparacion(textoBase);
    const prompt = item.json?.openrouter?.messages?.[0]?.content || meta.original_prompt || "";

    promptsPorTexto[textoNormalizado] = prompt;

    // Guardar info para debugging
    promptsDebugInfo.push({
      index,
      original: textoBase.substring(0, 100) + "...",
      normalized: textoNormalizado,
      hasPrompt: !!prompt,
      sld_nombre: meta.sld_nombre || "N/A"
    });
  }
});

// Log de debugging
console.log("=== DEBUG PROMPTS MATCHING ===");
console.log(`Total prompts procesados: ${Object.keys(promptsPorTexto).length}`);
promptsDebugInfo.forEach(info => {
  console.log(`[${info.index}] ${info.sld_nombre}: ${info.normalized.substring(0, 80)}...`);
});

// =======================================
// CONTENIDO POR SLIDE (CON MATCH NORMALIZADO)
// =======================================
const temasItems = obtenerItemsSeguro("Transformar a la estructura original1");
let itemsTemas = temasItems.slice(1);
let slideIndex = 1;
let matchStats = { total: 0, matched: 0, unmatched: 0 }; // Estadísticas

itemsTemas.forEach(item => {
  const tema = item.json || {};
  (tema.subtemas || []).forEach(sub => {
    (sub.contenido || []).forEach(parrafo => {
      const textoOriginal = parrafo.trim();
      const textoHTML = markdownToHTML(textoOriginal);

      // ✅ NORMALIZAR para buscar el prompt
      const textoParaBuscar = normalizarTextoParaComparacion(textoOriginal);
      const promptImagen = promptsPorTexto[textoParaBuscar];

      matchStats.total++;

      if (promptImagen) {
        matchStats.matched++;
      } else {
        matchStats.unmatched++;
        console.log(`⚠️ No match para: ${textoParaBuscar.substring(0, 100)}...`);
      }

      html += `<h3>Slide ${slideIndex} | Guión Teórico Detallado</h3><br>`;
      html += `<p><b>Sección:</b> ${tema.nombre || "Sin nombre"}<br>`;
      html += `<b>Subsección:</b> ${sub.nombre || "Sin nombre"}</p><br>`;
      html += `<p><b>Contenido del Slide</b></p>`;
      html += `<p>${textoHTML}</p><br>`;

      if (promptImagen) {
        html += `<p><b>Prompt para generar imagen:</b></p>`;
        html += `<p>${promptImagen}</p><br>`;
      } else {
        html += `<p><i>No se encontró prompt para este slide</i></p><br>`;
        // Debug info adicional
        html += `<details><summary>Debug info (texto normalizado)</summary>`;
        html += `<p><small>${textoParaBuscar}</small></p></details><br>`;
      }

      html += `<hr><br><br><br>`;
      slideIndex++;
    });
  });
});

// Log de estadísticas
console.log("=== MATCH STATISTICS ===");
console.log(`Total slides: ${matchStats.total}`);
console.log(`Matched prompts: ${matchStats.matched}`);
console.log(`Unmatched prompts: ${matchStats.unmatched}`);
console.log(`Match rate: ${((matchStats.matched / matchStats.total) * 100).toFixed(1)}%`);

// =======================================
// TRIVIA (CONTADOR GLOBAL)
// =======================================
const itemsPreguntas = obtenerItemsSeguro("Dividir preguntas y respuestas");
html += `<h2>🧠 Trivia — ${formulario.inf_nombre || "Trivia"}</h2><br>`;

const triviaPorNivel = { básico: [], intermedio: [], avanzado: [] };
itemsPreguntas.forEach(item => {
  const n = (item.json?.dificultad || "").toLowerCase();
  if (triviaPorNivel[n]) triviaPorNivel[n].push(item.json);
});

let contadorGlobal = 1;

function imprimirNivelHTML(nombre, preguntas, icono) {
  if (!preguntas.length) return;

  const nombreFormateado = nombre.charAt(0).toUpperCase() + nombre.slice(1);
  html += `<h3>${icono} Nivel ${nombreFormateado} (${preguntas.length})</h3><br>`;

  preguntas.forEach(p => {
    const pregunta = (p.pregunta || "").replace(/<\/?p>/g, "").trim();
    html += `<p><b>${contadorGlobal}. ${pregunta}</b></p><br>`;

    const letras = ["A", "B", "C", "D"];
    let correcta = "";
    (p.respuestas || []).forEach((r, i) => {
      html += `<p>${letras[i]}) ${r.texto || ""}</p>`;
      if (r.correcta) correcta = letras[i];
    });

    html += `<br><p><b>Respuesta correcta:</b> ${correcta}<br>`;
    html += `<b>Justificación:</b> ${p.justificacion || "No disponible"}<br>`;
    html += `<b>Nivel:</b> ${nombreFormateado}</p>`;
    html += `<br><br>`;
    contadorGlobal++;
  });
}

imprimirNivelHTML("básico", triviaPorNivel.básico, "🟢");
imprimirNivelHTML("intermedio", triviaPorNivel.intermedio, "🟡");
imprimirNivelHTML("avanzado", triviaPorNivel.avanzado, "🔴");

// =======================================
// SECCIÓN FINAL VACÍA
// =======================================
html += `<hr><br><br>`;
html += `<h2>📚 Referencias bibliográficas — ${formulario.inf_nombre || "TÍTULO NO ESPECIFICADO"}</h2>`;

// =======================================
// TEXTO PLANO (SIN CAMBIOS)
// =======================================
texto2 += `Título: ${formulario.inf_nombre || "Sin título"}\n\n`;
itemsTemas.forEach(item => {
  const tema = item.json || {};
  texto2 += `Tema: ${tema.nombre || "Sin nombre"}\n\n`;
  (tema.subtemas || []).forEach(sub => {
    texto2 += `${sub.nombre || "Sin nombre"}\n\n`;
    (sub.contenido || []).forEach(p => texto2 += p + "\n\n");
  });
});

// =======================================
// SALIDA
// =======================================
return [
  {
    json: {
      texto_completo: html.trim(),
      texto_contenido: texto2.trim(),
      debug_stats: matchStats // Opcional: incluir stats en output
    }
  }
];

// Obtener los datos del nodo anterior (slides)
const slides = $input.all();
const result = [];

// Valores por defecto
let estiloGrafico = "Ilustración digital semirealista, líneas definidas, sombreado suave, estilo limpio y profesional";
let audiencia = "estudiantes universitarios";

// =======================================
// Obtener información del formulario
// =======================================
try {
  const formulario = $items("Obtener campos del formulario")[0].json;

  let parametros = {};
  if (formulario.inf_parametros) {
    try {
      parametros = JSON.parse(formulario.inf_parametros);

      if (parametros.estilo_grafico) {
        const estiloMap = {
          "realista": "Ilustración digital semirealista, líneas definidas, sombreado suave, estilo limpio y profesional",
          "académico": "Estilo académico, ilustrativo, claro y educativo",
          "minimalista": "Estilo minimalista, líneas simples, colores planos",
          "cartoon": "Estilo cartoon, colores vibrantes, líneas expresivas",
          "técnico": "Estilo técnico, diagramas claros, precisión en detalles",
          "academico": "Estilo académico, ilustrativo, claro y educativo",
          "tecnico": "Estilo técnico, diagramas claros, precisión en detalles"
        };

        const estiloKey = parametros.estilo_grafico.toLowerCase();
        estiloGrafico =
          estiloMap[estiloKey] ||
          `Estilo gráfico: ${parametros.estilo_grafico}`;
      }

      if (parametros.audiencia) {
        audiencia = parametros.audiencia;
      }

    } catch (e) {
      console.error("Error al parsear inf_parametros:", e);
    }
  }
} catch (error) {
  console.log("No se encontró el nodo 'Obtener campos del formulario', usando valores por defecto");
}

// Encontrar el título de la portada (plantilla 8)
let tituloPortada = "";
const portada = slides.find(item => item.json.sld_plantilla === 8);
if (portada) {
  tituloPortada = portada.json.sld_titulo || "";
}

// Contador para los elementos que sí procesamos
let filteredIndex = 0;

// Procesar todos los slides
slides.forEach((slide, originalIndex) => {
  const slideData = slide.json;

  if (slideData.sld_plantilla === 2 || slideData.sld_plantilla === 8) {
    const textoLimpio = slideData.sld_texto1 ?
      slideData.sld_texto1.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim() :
      '';

    const textoCorto = textoLimpio;

    // ================================
    //  PROMPT OPTIMIZADO Y CONCISO
    // ================================
    let promptText = `CREATE AN IMAGE (generate the image directly, do not describe how to create it).

VISUAL STYLE:
- Semi-realistic illustration, high detail
- Clean lines, soft shading, professional
- No grainy texture, slightly stylized
- White background (mandatory)
- Style: ${estiloGrafico}

CONTENT CONTEXT:
- Main topic: ${tituloPortada || "Main topic"}
- Subtopic: ${slideData.sld_titulo || "Subtopic"}
- Target audience: ${audiencia}

TEXT TO ILLUSTRATE:
"${textoCorto}"

FUNCTIONAL REQUIREMENTS:
✓ Explicit didactic function (show processes, relationships, structures, or comparisons)
✓ Visual elements that effectively convey the text content
✓ Clear and suitable for the specified audience
✓ No purely aesthetic or ambiguous metaphors

CRITICAL RESTRICTIONS:
✗ No extensive text or titles (only brief Spanish labels if necessary)
✗ Text must be understandable WITHOUT the image
✗ No animation instructions

FORMAT: Horizontal 16:9 image, white background, professional educational quality.`;


    // ================================
    //  CONFIG PARA GEMINI 3 (según docs oficiales)
    // ================================
    const openrouterPayload = {
      model: "google/gemini-3-pro-image-preview",
      max_output_tokens: 4096,
      modalities: ["image", "text"], // Según documentación oficial
      image_config: {
        aspect_ratio: "16:9"
      },
      messages: [
        {
          role: "user",
          content: promptText // Enviado como string directo
        }
      ]
    };

    // Metadata
    const metadata = {
      prompt_index: filteredIndex,
      original_index: originalIndex,
      sld_nombre: slideData.sld_nombre || "",
      sld_titulo: slideData.sld_titulo || "",
      sld_id: slideData.sld_id || "",
      sld_plantilla: slideData.sld_plantilla || 0,
      sld_id_subseccion: slideData.sld_id_subseccion || "",
      original_prompt: promptText,
      estilo_grafico: estiloGrafico,
      audiencia: audiencia,
      titulo_portada: tituloPortada,
      texto_base: textoCorto
    };

    result.push({
      json: {
        openrouter: openrouterPayload,
        metadata: metadata
      },
      pairedItem: {
        item: originalIndex
      }
    });

    filteredIndex++;
  }
});

return result;

// Tomar todos los items de entrada
const inputItems = $input.all();

// Crear la salida
const output = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i].json;
  const choice = item.choices?.[0];
  const imageObj = choice?.message?.images?.[0];

  if (!imageObj) {
    // En lugar de error, crear un placeholder
    console.log(`⚠️ No se encontró imagen en el item ${i} (rec_id: ${item.rec_id}). Generando placeholder...`);

    // Crear una imagen PNG transparente mínima (1x1 pixel) en base64
    const placeholderBase64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";

    const fileName = `${item.rec_id}_placeholder.png`;

    output.push({
      json: {
        filename: fileName,
        rec_id: item.rec_id,
        nombre: item.rec_nombre,
        metadata: item.metadata,
        is_placeholder: true, // Marcador para identificar placeholders
        warning: "Imagen no generada - placeholder utilizado"
      },
      binary: {
        data: {
          data: placeholderBase64,
          mimeType: "image/png",
          fileName: fileName,
        },
      },
    });

  } else {
    // Procesar normalmente si existe la imagen
    const dataUrl = imageObj.image_url.url;
    const base64 = dataUrl.split(",")[1];
    const buffer = Buffer.from(base64, "base64");

    const fileName = `${item.rec_id}.png`;

    output.push({
      json: {
        filename: fileName,
        rec_id: item.rec_id,
        nombre: item.rec_nombre,
        metadata: item.metadata,
        is_placeholder: false
      },
      binary: {
        data: {
          data: buffer.toString("base64"),
          mimeType: "image/png",
          fileName: fileName,
        },
      },
    });
