const normalizarTexto = (texto) => {
  if (!texto) return "";

  return texto
    .replace(/<[^>]*>/g, '') // Quitar HTML
    .replace(/&times;/g, '×')
    .replace(/&plusmn;/g, '±')
    .replace(/&divide;/g, '÷')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
};

