secciones.forEach(seccion => {
  const nombre = seccion.nombre || "";
  const nombreLower = nombre.toLowerCase();

  // Regla de plantilla
  let plantilla = 2;
  if (nombreLower === "portada") plantilla = 8;
  else if (nombreLower === "bibliografía y más información") plantilla = 5;
  else if (nombreLower === "créditos") plantilla = 5;
  else if (nombreLower === "trivia") plantilla = 10;

  // Procesar cada subtema
  for (const sub of seccion.subtemas || []) {
    const subNombre = sub.nombre || "";

    // Si NO tiene contenido (portada, trivia, etc.)
    if (!sub.contenido || sub.contenido.length === 0) {
      let recursoURL = "";
      let referencia = "";

      // Para portada, verificar si hay recurso
      if (nombreLower === "portada" && portadaSlide) {
        if (portadaSlide.sld_fondo) {
          recursoURL = `https://bucketvirtualpro.s3.amazonaws.com/infografiasHtm/${infografiaId}/images/${portadaSlide.sld_fondo}.png`;
        }
      }

      rows.push({
        seccion: nombre,
        subseccion: subNombre,
        slide: 1,
        plantilla,
        texto: sub.titulo ? sub.titulo : "",
        recurso: recursoURL,
        referencia: referencia
      });
      continue;
    }

    // Si tiene contenido (slides con párrafos)
    sub.contenido.forEach((texto, index) => {
      const slide = index + 1;

      // Normalizar texto para búsqueda de recursos
      const textoNormalizado = normalizarTexto(texto);

      let recursoURL = "";
      let referencia = "";

      // 1. Buscar recurso para este texto
      if (mapaRecursos.has(textoNormalizado)) {
        const recursoData = mapaRecursos.get(textoNormalizado);
        recursoURL = `https://bucketvirtualpro.s3.amazonaws.com/infografiasHtm/${infografiaId}/images/${recursoData.recurso}.png`;
      } else {
        // Búsqueda aproximada si no hay match exacto
        let encontrado = false;
        for (const [textoSlide, recursoData] of mapaRecursos.entries()) {
          // Verificar si el texto normalizado es muy similar (primeros 100 caracteres)
          const substring1 = textoNormalizado.substring(0, 100);
          const substring2 = textoSlide.substring(0, 100);

          if (substring1 === substring2 && substring1.length > 50) {
            recursoURL = `https://bucketvirtualpro.s3.amazonaws.com/infografiasHtm/${infografiaId}/images/${recursoData.recurso}.png`;
            encontrado = true;
            break;
          }
        }

        if (!encontrado && textoNormalizado.length > 20) {
          console.log(`ℹ️ No se encontró recurso para: "${texto.substring(0, 60)}..."`);
        }
      }

      // 2. Buscar referencia para este texto (usando texto sin normalizar)
      const textoLimpioReferencia = texto.replace(/\s+/g, ' ').trim();
      if (mapaReferencias[textoLimpioReferencia]) {
        referencia = mapaReferencias[textoLimpioReferencia];
      } else if (textoLimpioReferencia.length > 10) {
        console.log(`ℹ️ No se encontró referencia para: "${textoLimpioReferencia.substring(0, 60)}..."`);
      }

      rows.push({
        seccion: index === 0 ? nombre : "",
        subseccion: index === 0 ? subNombre : "",
        slide,
        plantilla,
        texto,
        recurso: recursoURL,
        referencia: referencia
      });
    });
  }
});

