// FUNCIÓN HELPER PARA AGREGAR PUNTO FINAL
// =======================================
function agregarPuntoFinal(texto) {
  if (!texto || typeof texto !== 'string') return texto;

  const textoTrimmed = texto.trim();
  if (textoTrimmed.length === 0) return texto;

  const ultimoCaracter = textoTrimmed[textoTrimmed.length - 1];

  // Verificar si termina con signo de puntuación válido
  const signosPuntuacion = ['.', '!', '?', ':', ';'];

  if (!signosPuntuacion.includes(ultimoCaracter)) {
    return textoTrimmed + '.';
  }

  return textoTrimmed;
}

