// =======================================
// FUNCIÓN PARA CONVERTIR MARKDOWN A HTML
// =======================================
function markdownToHTML(text) {
    if (!text || typeof text !== 'string') return text;

    let converted = text;

    // 1. Convertir saltos de línea (ambos formatos)
    converted = converted.replace(/\\n\\n/g, '<br><br>');
    converted = converted.replace(/\n\n/g, '<br><br>');

    // 2. Convertir encabezados (antes de negritas para evitar conflictos)
    converted = converted.replace(/####\s+(.+?)(?=<br>|$)/g, '<h4>$1</h4>');
    converted = converted.replace(/###\s+(.+?)(?=<br>|$)/g, '<h3>$1</h3>');

    // 3. Convertir listas ordenadas
    // Patrón: captura bloques de líneas que empiezan con "1.", "2.", etc.
    converted = converted.replace(/(?:^|\n)((?:\d+\.\s+.+(?:\n|$))+)/gm, function(match, listContent) {
        const items = listContent.trim().split(/\n/).map(line => {
            return line.replace(/^\d+\.\s+/, '').trim();
        }).filter(item => item.length > 0);

        if (items.length === 0) return match;

        const listItems = items.map(item => `<li>${item}</li>`).join('');
        return `<ol>${listItems}</ol>`;
    });

    // 4. Convertir listas no ordenadas
    // Patrón: captura bloques de líneas que empiezan con "-"
    converted = converted.replace(/(?:^|\n)((?:-\s+.+(?:\n|$))+)/gm, function(match, listContent) {
        const items = listContent.trim().split(/\n/).map(line => {
            return line.replace(/^-\s+/, '').trim();
        }).filter(item => item.length > 0);

        if (items.length === 0) return match;

        const listItems = items.map(item => `<li>${item}</li>`).join('');
        return `<ul>${listItems}</ul>`;
    });

    // 5. Convertir negrita y cursiva combinadas (debe ir antes que negrita o cursiva solas)
    converted = converted.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');

    // 6. Convertir negrita
    converted = converted.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

    // 7. Convertir cursiva
    converted = converted.replace(/\*(.+?)\*/g, '<em>$1</em>');

    // 8. Limpiar saltos de línea sueltos que quedaron
    converted = converted.replace(/\n/g, ' ');

    return converted;
}

