  let parsed;
  try {
    parsed = JSON.parse(output);
  } catch (e) {
    continue;
  }

  // La IA siempre devuelve un ARRAY de bloques
  if (!Array.isArray(parsed)) continue;

  for (const bloque of parsed) {
    // Validación mínima de estructura esperada
    if (
      !bloque ||
      typeof bloque !== 'object' ||
      !bloque.nombre ||
      !Array.isArray(bloque.subtemas)
    ) {
      continue;
    }

    // ============================================
    // CORRECCIÓN: Limpiar caracteres escapados en el texto Markdown
    // ============================================
    bloque.subtemas = bloque.subtemas.map(subtema => {
      if (Array.isArray(subtema.contenido)) {
        subtema.contenido = subtema.contenido.map(item => {
          if (item.texto) {
            // Remover backslashes innecesarios que escapan caracteres Markdown
            item.texto = item.texto
              .replace(/\\\*/g, '*')      // \* → *
              .replace(/\\_/g, '_')       // \_ → _
              .replace(/\\#/g, '#')       // \# → #
              .replace(/\\-/g, '-')       // \- → -
              .replace(/\\\[/g, '[')      // \[ → [
              .replace(/\\\]/g, ']')      // \] → ]
              .replace(/\\\(/g, '(')      // \( → (
              .replace(/\\\)/g, ')')      // \) → )
              .replace(/\\n\\n/g, '\n\n'); // Preservar saltos de línea dobles
          }
          return item;
        });
      }
      return subtema;
    });

    salida.push({
      json: bloque
    });
  }
}

return salida;

