        referencia: index === 0 ? contenido.referencia : ""
      });
    });

  });
});

// ===============================
// 4. COMBINAR TODO EN EL ORDEN CORRECTO
// ===============================
const linealFinal = [
  ...portada,
  ...contenidos,
  ...trivia,
  ...bibliografia,
  ...creditos
];

// ===============================
// 5. OUTPUT
// ===============================
return linealFinal.map(json => ({ json }));
